"C:\\Windows\\System32\\WindowsPowerShell\\v1.0\\powershell.exe" -Command '$repoPath = '"'C:\\Users\\User\\codex_github_bridge\\projects\\akvatonus.ru';
"'$subdirs = @(
  '"'screens\\desktop',
  'screens\\mobile',
  'docs',
  'source',
  'assets'
);
New-Item -ItemType Directory -Path "'$repoPath -Force | Out-Null;
foreach ($subdir in $subdirs) {
  New-Item -ItemType Directory -Path (Join-Path $repoPath $subdir) -Force | Out-Null;
}
Get-ChildItem -Path $repoPath -Directory -Recurse | ForEach-Object { $_.FullName }'

